117	/// Unique identifier for an action.
118	pub type ActionID = u64;
119	
120	/// A representation of side effects that are happening, or could be happening, right now
121	/// in the background.
122	#[derive(Debug, Clone)]
123	pub struct Action {
124	    /// Id for the action
125	    #[allow(dead_code)]
126	    pub action_id: ActionID,
127	
128	    /// The action's side effects are completed.
