2148	            .thread_tree
2149	            .my_thread_group(detpid)
2150	            .into_iter()
2151	            .any(|tid| self.next_turns.contains_key(&tid));
2152	        if !live_process_thread {
2153	            let _ = self.begin_physical_process_exit(*detpid);
2154	            self.logically_exited_processes.insert(*detpid);
2155	            if let Some(parent) = self.thread_tree.parent_process(detpid) {
2156	                self.wake_child_waiters(parent, *detpid);
