3487	    /// Name every blocked class that is actually holding the run.
3488	    ///
3489	    /// Derived from state rather than passed in by the caller, so the headline
3490	    /// cannot contradict the body it sits above. Branch order alone would
3491	    /// mis-file a genuine futex deadlock that merely has a saturated timer
3492	    /// registered: `step2d_handle_empty_queue` reaches the indefinite arm
3493	    /// whenever *any* timed waiter exists, so a caller-supplied headline would
3494	    /// read "waiting indefinitely" while the futex pool is the real story. The
3495	    /// body always listed both; the headline is what lands in a bug report.
3496	    fn describe_terminal_waiters(&self) -> String {
3497	        let mut classes: Vec<&str> = Vec::new();
3498	        if !self.blocked.no_futex_waiters() {
3499	            classes.push("thread(s) waiting on futex");
3500	        }
3501	        if !self.blocked.timed_waiters.is_empty() {
3502	            classes.push(
3503	                "thread(s) waiting indefinitely (pause, or a timer beyond the end of logical time)",
3504	            );
3505	        }
3506	        if !self.blocked.rt_sigsuspend_blockers.is_empty() {
3507	            classes.push("thread(s) waiting in rt_sigsuspend with no possible signal");
3508	        }
3509	        if classes.is_empty() {
3510	            // Defensive: every caller fires with at least one class present.
3511	            "thread(s) blocked with no possible wake".to_owned()
3512	        } else {
3513	            classes.join(", and ")
3514	        }
3515	    }
