3719	        if self.run_queue.is_empty() {
3720	            if !self.pending_physical_process_exits.is_empty() {
3721	                // The SaBRe plugin has run the child process's logical exit hook, but the ptrace
3722	                // supervisor has not received its final wait status. Fast-forwarding the next
3723	                // timer here can fire a parent's timeout before the child becomes waitable.
3724	                trace!(
3725	                    "waiting for physical process exits before empty-queue timer fast-forward: {:?}",
3726	                    self.pending_physical_process_exits
3727	                );
3728	                std::thread::yield_now();
3729	                return Err(SkipTurn);
3730	            }
3731	            // When the run queue is empty, we sometimes need to give things a kick.
3732	            if futex_empty && timed_empty && external_waits_empty && rt_sigsuspend_empty {
3733	                // `info!`, and that level is load-bearing. Restored from `trace!`
3734	                // by owner ruling after 08ff51a33e demoted it.
3735	                //
3736	                // THE DEMOTION'S ARGUMENT AND WHY IT WAS REJECTED. It ran: how
3737	                // many times this branch is reached depends on when the host
3738	                // delivers a child's final wait status, that is an external
3739	                // real-time event, an INFO line driven by one is a determinism
3740	                // hazard by construction, so keep the loop sub-INFO. The
3741	                // measurement offered with it was real -- over 312 concurrent
3742	                // SaBRe cell-runs, 4 diverged, and in each the whole difference
3743	                // was this line plus one unrelated WARN.
3744	                //
3745	                // The owner's ruling: this fizzle is part of the deterministic
3746	                // scheduling model, not record/replay external-IO terrain, so it
3747	                // SHOULD be a deterministic function of detcore scheduling. If it
3748	                // is not, that is a hermit DEFECT, and demoting the line hid the
3749	                // defect instead of fixing it. The previous note ended "do not
3750	                // promote this back without making the host's wait-status
3751	                // delivery deterministic, which is not possible" -- but making it
3752	                // deterministic is exactly the work owed, not a reason to stop
3753	                // reporting it.
3754	                //
3755	                // AND THE DEFECT IS REAL AND LARGER THAN THIS LINE. Measured
3756	                // 2026-08-24 on the CI-staged SaBRe artifact: a guest that forks
3757	                // and reaps its child with `wait4(WNOHANG)` diverges 36 of 50
3758	                // under `--verify-strict`, while ptrace is 0 of 50 on the same
3759	                // guest. The divergence is not confined to logging -- the guest
3760	                // ITSELF executes different work, 355 syscalls with 4 `wait4`
3761	                // calls in one run against 354 with 3 in the other. The
3762	                // scheduler's committed non-poll decisions are byte-identical
3763	                // (68 in both), so what varies is how many times the parent is
3764	                // told "not yet". Silencing this line would have left that
3765	                // unreported.
3766	                //
3767	                // If this line is noisy again, the fix is to make a child's exit
3768	                // become observable to its parent at a deterministic point, not
3769	                // to lower the level.
3770	                if enabled!(Level::INFO) {
3771	                    let record_suffix = crate::detlog::record_suffix(
3772	                        crate::detlog::DetLogEvent::SchedulerEmptyQueueKick,
3773	                    );
3774	                    info!(
3775	                        "scheduler (step2_process_blocked): zero threads left anywhere, fizzling.{}",
3776	                        record_suffix
3777	                    );
3778	                }
