3785	                // `LogicalTime::INDEFINITE` is the sentinel a `pause(2)` (or a
3786	                // far-future timer that saturated the clock) registers to mean "no
3787	                // deadline; wake me on a signal". Because the map is ordered, an
3788	                // indefinite front entry means every pending timed event is
3789	                // indefinite, so no amount of virtual time can fire any of them.
3790	                // Popping it anyway would jump global virtual time by ~584 years and
3791	                // grant the sleep as a `ResumeStatus::Normal` wake, which is exactly
3792	                // the internal violation `Detcore::handle_pause` refuses to accept.
3793	                let next_deadline = self
3794	                    .blocked
3795	                    .timed_waiters
3796	                    .next_deadline()
3797	                    .expect("internal error: no timed events found");
