3856	    /// Step: Find the next thread to run for this scheduling run.
3857	    /// Sometimes the next thread is from the run queue, but it can also be a timed event.
3858	    /// Return `None` if the queue is empty.
3859	    ///
3860	    /// This is a "peek" in the sense that it leaves the thread in the run queue.
3861	    fn step3_peek(&mut self) -> Option<(DetTid, Ivar<SchedRequest>, Ivar<SchedResponse>)> {
3862	        // Re-admit any happens-before threads whose gate opened since last turn.
3863	        // Must precede `tentative_pop_next`: the run queue forbids pushes while a
3864	        // selection transaction is live.
3865	        self.hb_flush_wakes();
3866	        debug!(
3867	            "[sched-step3] Stepping scheduler, queue len {}, current turn {}, committed_time {}",
3868	            self.run_queue.len(),
3869	            self.turn,
3870	            self.committed_time
3871	        );
3872	
3873	        // Enable for FULL detail:
3874	        {
3875	            trace!(
3876	                "[sched-step3] queue {:?}, io-blocked {:?}, next_turns: ",
3877	                &self.run_queue, self.blocked.external_io_blockers
3878	            );
3879	            for (dtid, nxt) in self.next_turns.iter() {
3880	                trace!(" ==> dtid {}, req {}, resp {}", dtid, nxt.req, nxt.resp);
3881	            }
3882	            if !self.blocked.timed_waiters.is_empty() {
3883	                trace!("Timed events: {:?}", self.blocked.timed_waiters);
3884	            }
3885	        }
3886	
3887	        if self.run_queue.is_empty() {
3888	            None
3889	        } else {
3890	            let next_dtid = if self.vfork_barriers.is_empty() {
3891	                self.run_queue.tentative_pop_next().expect("impossible")
3892	            } else {
3893	                let child = self
3894	                    .vfork_barriers
3895	                    .values()
3896	                    .flatten()
3897	                    .find(|child| self.run_queue.contains_tid(**child))
3898	                    .copied()?;
3899	                self.run_queue
3900	                    .tentative_pop_tid(child)
3901	                    .expect("vfork child disappeared from run queue")
3902	            };
3903	            let nextturn = self.next_turns.get(&next_dtid).unwrap_or_else(|| {
3904	                panic!(
3905	                "[sched-step3] internal error: dettid {} queued but missing entry in next_turns",
3906	                    next_dtid
3907	            )
3908	            });
