3957	    /// Simply advance the turn. This does NOT remove any threads from the
3958	    /// runqueue; callers must maintain `run_queue`/`blocking` invariants.
3959	    fn skip_turn(&mut self) -> Result<(), SkipTurn> {
3960	        self.turn += 1; // Skipping the turn advances the turn.
3961	        Err(SkipTurn)
3962	    }
