5062	    pub(crate) fn child_runs_first_post_fork(&mut self, mode: RunsPostFork) -> bool {
5063	        match mode {
5064	            RunsPostFork::Child => true,
5065	            RunsPostFork::Parent => false,
5066	            RunsPostFork::Random => self.post_fork_prng.random(),
