7166	            .next_turns
7167	            .get(&target)
7168	            .and_then(|next_turn| next_turn.req.try_read())
7169	            .and_then(Result::ok)
7170	            .expect("the target should still hold a request");
7171	        assert!(
7172	            resources.resources.len() <= 1,
