    );
    assert!(
        scheduler
            .step5_guest_unblock(target, &resources, &selected_response)
            .is_ok()
    );
    assert!(matches!(
        response.try_read(),
        Some(SchedResponse::Signaled(Some(signals)))
            if signals == vec![
                SigWrapper::from(Signal::SIGUSR1),
                SigWrapper::from(Signal::SIGUSR2),
                SigWrapper::from(Signal::SIGTERM),
            ]
    ));
}

