8036	    /// The `SignalEvt` arm is the sub-case whose behaviour this change actually
8037	    /// alters, and it is reachable with no `pause` anywhere.
8038	    ///
8039	    /// `handle_timer_settime` adds a guest-supplied duration to now, and
8040	    /// `LogicalTime`'s `Add` saturates, so an absurdly far-future POSIX timer
8041	    /// (issue #219, the Java case) lands on `LogicalTime::INDEFINITE` and
8042	    /// `register_posix_timer` inserts it verbatim. Previously `step2d` popped it,
8043	    /// fast-forwarded the clock ~584 years, and dispatched to `fire_alarm`, which
8044	    /// -- unlike the `ThreadEvt` arm -- does NOT abort: it delivered a bogus
8045	    /// year-2554 signal and the guest carried on. That is now a terminal
8046	    /// deadlock, which is the faithful answer, because Linux will not fire that
8047	    /// timer either and those threads genuinely hang.
8048	    #[test]
8049	    fn saturated_posix_timer_alone_is_a_deadlock_not_a_bogus_signal() {
8050	        let config = Config::default();
8051	        let mut scheduler = Scheduler::new(&config);
8052	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
8053	        let initial_time = global_time.lock().unwrap().as_nanos();
8054	        let process = DetPid::from_raw(100);
8055	
8056	        // The real production entry point, with the deadline a saturating add
8057	        // produces. No `pause`, no `ThreadEvt`.
8058	        scheduler.register_posix_timer(
8059	            process,
8060	            process,
8061	            7,
8062	            Some(LogicalTime::MAX - LogicalTime::from_nanos(0)),
8063	            LogicalTime::ZERO,
8064	            Signal::SIGALRM,
8065	        );
8066	        assert_eq!(
8067	            scheduler.blocked.timed_waiters.next_deadline(),
8068	            Some(LogicalTime::INDEFINITE),
8069	            "a saturated timer must land on the no-deadline sentinel"
8070	        );
8071	
8072	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
8073	
8074	        let report = scheduler
8075	            .take_terminal_deadlock()
8076	            .expect("a saturated timer with nothing runnable is a terminal deadlock");
8077	        assert!(
8078	            report.contains("thread(s) waiting indefinitely"),
8079	            "unexpected report:\n{report}"
8080	        );
8081	        // The signal was NOT delivered and the clock did NOT jump to the end of
8082	        // logical time: both are what the old fast-forward did here.
