332	+struct Payload {
333	+    label: &'static str,
334	+    _send_only: Cell<u8>,
335	+}
336	+
337	+fn payload(label: &'static str) -> (PanicPayload, usize) {
338	+    let value = Box::new(Payload {
339	+        label,
340	+        _send_only: Cell::new(1),
341	+    });
342	+    let address = std::ptr::from_ref(value.as_ref()) as usize;
343	+    (value, address)
344	+}
345	+
346	+fn assert_payload(actual: &PanicPayload, address: usize, label: &str) {
347	+    let actual = actual.downcast_ref::<Payload>().unwrap();
348	+    assert_eq!(std::ptr::from_ref(actual) as usize, address);
349	+    assert_eq!(actual.label, label);
350	+}
