352	+#[derive(Default)]
353	+struct Counts {
354	+    polls: AtomicUsize,
355	+    drops: AtomicUsize,
356	+    failure_drops: AtomicUsize,
357	+}
358	+
359	+struct Cleanup {
360	+    counts: Arc<Counts>,
361	+    output: Option<Result<usize>>,
362	+    transfer: Option<(SharedHandlerSignal, Error)>,
363	+    retained: Option<Weak<Error>>,
364	+    poll_panic: Option<PanicPayload>,
365	+    drop_panic: Option<PanicPayload>,
366	+}
367	+
368	+impl Future for Cleanup {
369	+    type Output = Result<usize>;
370	+
371	+    fn poll(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<Self::Output> {
372	+        let this = self.get_mut();
373	+        this.counts.polls.fetch_add(1, Ordering::SeqCst);
374	+        if let Some((slot, error)) = this.transfer.take() {
375	+            let mut slot = slot.lock().unwrap();
376	+            assert!(slot.is_none());
377	+            *slot = Some(HandlerSignal::RuntimeError(error));
378	+            // Poison the actual slot after transferring the sole error owner.
379	+            if let Some(payload) = this.poll_panic.take() {
380	+                resume_unwind(payload);
381	+            }
382	+        }
383	+        if let Some(payload) = this.poll_panic.take() {
384	+            resume_unwind(payload);
385	+        }
386	+        this.output.take().map_or(Poll::Pending, Poll::Ready)
387	+    }
388	+}
389	+
390	+impl Drop for Cleanup {
391	+    fn drop(&mut self) {
392	+        assert_eq!(self.counts.drops.fetch_add(1, Ordering::SeqCst), 0);
393	+        if let Some(retained) = &self.retained {
394	+            assert!(
395	+                retained.upgrade().is_some(),
396	+                "cleanup dropped its selected error"
397	+            );
398	+        }
399	+        if let Some(payload) = self.drop_panic.take() {
400	+            resume_unwind(payload);
401	+        }
402	+    }
403	+}
404	+
405	+struct Failure {
406	+    ready: Arc<AtomicBool>,
407	+    counts: Arc<Counts>,
408	+    drop_panic: Option<PanicPayload>,
409	+}
410	+
411	+impl Future for Failure {
412	+    type Output = ();
413	+
414	+    fn poll(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<()> {
415	+        if self.ready.load(Ordering::SeqCst) {
416	+            Poll::Ready(())
417	+        } else {
418	+            Poll::Pending
419	+        }
420	+    }
421	+}
422	+
423	+impl Drop for Failure {
424	+    fn drop(&mut self) {
425	+        assert_eq!(self.counts.drops.load(Ordering::SeqCst), 1);
426	+        assert_eq!(self.counts.failure_drops.fetch_add(1, Ordering::SeqCst), 0);
427	+        if let Some(payload) = self.drop_panic.take() {
428	+            resume_unwind(payload);
429	+        }
430	+    }
431	+}
432	+
433	+fn effects_error() -> (Error, Weak<Error>) {
434	+    let error = Arc::new(Error::SignalEffects {
435	+        cause: Arc::new(Error::Reverie(Errno::EIO.into())),
436	+        dequeues: Vec::new(),
437	+        acknowledged_through: 17,
438	+        publications: Vec::new(),
439	+        raw_result: Some(-i64::from(libc::EFAULT)),
440	+        context: None,
441	+    });
442	+    let weak = Arc::downgrade(&error);
443	+    (Error::SharedFailure(error), weak)
444	+}
445	+
446	+fn assert_effects_error(error: &Error, expected: &Weak<Error>) {
447	+    let Error::SharedFailure(error) = error else {
448	+        panic!("cleanup replaced its selected error");
449	+    };
450	+    assert_eq!(Arc::as_ptr(error), expected.as_ptr());
451	+    assert_eq!(Arc::strong_count(error), 1);
452	+    assert!(matches!(error.as_ref(), Error::SignalEffects {
453	+        cause, acknowledged_through: 17, raw_result: Some(raw), ..
454	+    } if matches!(cause.as_ref(), Error::Reverie(reverie::Error::Errno(errno)) if *errno == Errno::EIO)
455	+        && *raw == -i64::from(libc::EFAULT)));
456	+}
