44	    async fn complete_signal_effects(
45	        &mut self,
46	        raw: Option<i64>,
47	    ) -> Result<Option<reverie::SignalDequeue>> {
48	        let mut last = None;
49	        if self.executor.signal_dequeue_front().is_some() {
50	            // Stored outside this future: cancellation during the notification
51	            // must retain the real copyout errno along with the removal.
52	            self.executor.retain_signal_effect_result(raw);
53	        }
54	        loop {
55	            let next = futures::future::poll_fn(|cx| self.executor.poll_signal_dequeue(cx)).await;
56	            let effect = match next {
57	                Ok(Some(effect)) => effect,
58	                Ok(None) => break,
59	                Err(error) => return Err(self.executor.with_signal_effects(error, raw)),
60	            };
61	            self.executor.retain_signal_dequeue(effect);
62	            let previous = self
63	                .executor
64	                .set_signal_guard(SignalGuard::DequeueNotification);
65	            self.notifying_dequeue = true;
66	            let tool = self.process_state.clone();
67	            let result = tool.handle_signal_dequeue(self, effect).await;
68	            self.notifying_dequeue = false;
69	            self.executor.set_signal_guard(previous);
70	            if let Err(errno) = result {
71	                return Err(self
72	                    .executor
73	                    .with_signal_effects(Error::Reverie(errno.into()), raw));
74	            }
75	            if let Err(errno) = self.executor.acknowledge_signal_dequeue(effect) {
76	                return Err(self
77	                    .executor
78	                    .with_signal_effects(Error::Reverie(errno.into()), raw));
79	            }
80	            last = Some(effect);
81	        }
82	        Ok(last)
83	    }
