236	// Give an already-ready consuming cleanup its result even after failure. A
237	// blocked FIFO predecessor or notification must still observe run termination.
238	// This is deliberately different from ordinary callbacks, where failure wins
239	// before the callback is polled. No cancellation acknowledges a removal.
240	async fn drive_signal_cleanup<T>(
241	    future: impl Future<Output = T>,
242	    handler_signal: SharedHandlerSignal,
243	    pending_children: SharedChildStarts,
244	    failure: impl Future<Output = ()>,
245	) -> crate::failure::owned_future::CaughtFuture<HandlerOutcome<T>> {
246	    // Cancellation is selected by the owning driver, so it still catches
247	    // destruction of the actual callback allocation before returning. Dropping
248	    // a pending nested driver would bypass that completion protocol.
249	    drive_handler_completion_inner(
250	        future,
251	        handler_signal,
252	        pending_children,
253	        failure,
254	        None,
255	        HandlerFailureOrder::AfterReadyCleanup,
256	    )
257	    .await
258	}
