260	/// Signal-dequeue notifications cannot create a child: the guest is under
261	/// `SignalGuard::DequeueNotification`, and `signal_injection_allowed` rejects
262	/// every injected syscall before `complete_injection` can publish a fork or
263	/// thread start. The lifecycle process context independently rejects fork and
264	/// clone actions before they can spawn. Keep that production invariant
265	/// explicit. Detect and recover it here without joining: `CancelAfterFailure`
266	/// is a terminal command, so the finalized parent error must be published
267	/// before any child receives it.
268	fn signal_cleanup_child_start_violation(
269	    pending_children: &SharedChildStarts,
270	) -> Option<Error> {
271	    let poisoned = pending_children.is_poisoned();
272	    let has_children = !pending_children
273	        .lock()
274	        .unwrap_or_else(|poisoned| poisoned.into_inner())
275	        .is_empty();
276	    if poisoned {
277	        // The completion driver already caught the panic that poisoned this
278	        // lock. Recovery must not replace or obscure that owned payload.
279	        pending_children.clear_poison();
280	    }
281	    if !has_children && !poisoned {
282	        return None;
283	    }
284	    Some(Error::UnexpectedVcpuExit(
285	        match (has_children, poisoned) {
286	            (true, true) => {
287	                "signal dequeue notification created a child start and poisoned its child-start state"
288	            }
289	            (true, false) => {
290	                "signal dequeue notification created a child start despite its injection guard"
291	            }
292	            (false, true) => "signal dequeue notification poisoned its child-start state",
293	            (false, false) => unreachable!(),
294	        }
295	        .to_owned(),
296	    ))
297	}
