299	fn finish_signal_cleanup<T>(
300	    backend: &mut KvmBackend,
301	    executor: &mut ElfExecutor,
302	    completion: crate::failure::owned_future::CaughtFuture<HandlerOutcome<Result<T>>>,
303	    pending_children: &SharedChildStarts,
304	    raw: Option<i64>,
305	) -> Result<()> {
306	    let violation = signal_cleanup_child_start_violation(pending_children);
307	    let outcome = backend.finish_handler_completion(
308	        completion,
309	        Ok(()),
310	        std::convert::identity,
311	    );
312	    let result = match outcome {
313	        Err(error) => Err(error),
314	        Ok(HandlerOutcome::Returned(result)) => result.map(|_| ()),
315	        Ok(HandlerOutcome::RuntimeError(error)) => Err(error),
316	        Ok(HandlerOutcome::ParkedCancelled(_)) | Ok(HandlerOutcome::RunFailed) => {
317	            Err(Error::RunAborted)
318	        }
319	        Ok(_) => Err(Error::UnexpectedVcpuExit(
320	            "nonlocal operation during dequeue acknowledgment".to_owned(),
321	        )),
322	    };
323	    let Some(violation) = violation else {
324	        return result.map_err(|error| executor.with_signal_effects(error, raw));
325	    };
326	
327	    // A real selected error or panic remains primary. A derived RunAborted
328	    // cannot publish a terminal transition, so promote the invariant failure
329	    // ahead of it. Attach the signal ledger/raw errno exactly once and before
330	    // publication.
331	    let error = match result {
332	        Ok(()) => violation,
333	        Err(error) if matches!(error.primary(), Error::RunAborted) => {
334	            violation.with_cleanup(vec![error])
335	        }
336	        Err(error) => error.with_cleanup(vec![violation]),
337	    };
338	    let error = executor.with_signal_effects(error, raw);
339	    let error = backend.report_tool_failure("Tool callback", error);
340	    let error = match backend
341	        .settle_unstarted_tool_children_after_failure(executor, pending_children)
342	    {
343	        Ok(()) => error,
344	        Err(cleanup) => error.with_cleanup(vec![
345	            cleanup.cleanup("signal-cleanup child retirement failed")
346	        ]),
347	    };
348	    Err(error)
349	}
