                    let mut guest = KvmGuest::new(
                        pid,
                        pid,
                        tool.clone(),
                        memory.clone(),
                        &[],
                        registers,
                        &mut state,
                        &mut adapter,
                        global.as_ref(),
                        Some(global.clone()),
                        &(),
                        &subscriptions,
                        signal.clone(),
                        starts.clone(),
