223	pub(crate) fn is_backend_owned_syscall(number: u64, thread_ownership: ThreadOwnership) -> bool {
224	    // `futex` ownership follows the thread's `ThreadOwnership`, so it can never
225	    // disagree with how that thread executes:
226	    //
227	    // * `ThreadOwnership::Tool`: every thread — root and worker alike — is
228	    //   registered in the Tool's (Detcore's) scheduler. `futex` must therefore
229	    //   route to the Tool so that a join's `FUTEX_WAIT` becomes a logical
230	    //   scheduler wait woken by the exiting worker's logical `CLONE_CHILD_CLEARTID`
231	    //   wake. Executing it as a real host futex here deadlocks: the exiting
232	    //   worker's wake is only simulated inside Detcore and never reaches a real
233	    //   host futex word, so the waiter sleeps forever.
234	    // * `ThreadOwnership::Host`: workers run uninstrumented outside the Tool's
235	    //   scheduler, so the root's futex must use the same host-backed words as
236	    //   those siblings and stays backend-owned.
237	    if number == libc::SYS_futex as u64 {
238	        return thread_ownership.futex_is_host_owned();
239	    }
240	    // QEMU's root event loop waits on worker eventfds. KVM syscall
241	    // injection cannot perform ppoll, so use translated host descriptors in
242	    // either ownership mode.
243	    if number == libc::SYS_ppoll as u64 {
244	        return true;
245	    }
246	
247	    // Host-owned workers execute outside the Tool and can create descriptors
248	    // that the root event loop consumes. Their scalar and vectored reads must
249	    // therefore use the backend's shared descriptor table. Tool-owned workers,
250	    // however, are registered with the Tool's scheduler, so their reads must
251	    // reach Tool::handle_syscall_event. In particular, Detcore makes internal
252	    // pipes physically nonblocking while keeping them logically blocking; if
253	    // the backend consumes those reads itself, the implementation-only EAGAIN
254	    // leaks to the guest instead of entering Detcore's polling retry path.
255	    thread_ownership.executes_on_host()
256	        && (number == libc::SYS_read as u64 || number == libc::SYS_readv as u64)
257	}
